"use client";

import React, { useRef } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { RotateCcwIcon } from "lucide-react";

import { useSliderWithInput } from "@/registry/ui-basic/hooks/useSliderWithInput";

export default function Component() {
	// Create refs to store reset functions
	const resetFunctionsRef = useRef<(() => void)[]>([]);

	// Function to reset all sliders to default
	const resetAll = () => {
		resetFunctionsRef.current.forEach((resetFn) => resetFn());
	};

	// Function to register reset functions
	const registerResetFunction = (resetFn: () => void, index: number) => {
		resetFunctionsRef.current[index] = resetFn;
	};

	return (
		<div className="space-y-4">
			<legend className="text-foreground text-sm font-medium">
				Object position
			</legend>
			<div className="space-y-2">
				<SliderWithInput
					minValue={-10}
					maxValue={10}
					initialValue={[-2]}
					defaultValue={[0]}
					label="X"
					onRegisterReset={(resetFn) => registerResetFunction(resetFn, 0)}
				/>
				<SliderWithInput
					minValue={-10}
					maxValue={10}
					initialValue={[4]}
					defaultValue={[0]}
					label="Y"
					onRegisterReset={(resetFn) => registerResetFunction(resetFn, 1)}
				/>
				<SliderWithInput
					minValue={-10}
					maxValue={10}
					initialValue={[2]}
					defaultValue={[0]}
					label="Z"
					onRegisterReset={(resetFn) => registerResetFunction(resetFn, 2)}
				/>
			</div>
			<Button className="w-full" variant="outline" onClick={resetAll}>
				<RotateCcwIcon
					className="-ms-1 opacity-60"
					size={16}
					aria-hidden="true"
				/>
				Reset
			</Button>
		</div>
	);
}

function SliderWithInput({
	minValue,
	maxValue,
	initialValue,
	defaultValue,
	label,
	onRegisterReset,
}: {
	minValue: number;
	maxValue: number;
	initialValue: number[];
	defaultValue: number[];
	label: string;
	onRegisterReset: (resetFn: () => void) => void;
}) {
	const {
		sliderValue,
		inputValues,
		validateAndUpdateValue,
		handleInputChange,
		handleSliderChange,
		resetToDefault,
	} = useSliderWithInput({ minValue, maxValue, initialValue, defaultValue });

	// Register the reset function when the component mounts
	React.useEffect(() => {
		onRegisterReset(resetToDefault);
	}, [onRegisterReset, resetToDefault]);

	return (
		<div className="flex items-center gap-2">
			<Label className="text-muted-foreground text-xs">{label}</Label>
			<Slider
				className="grow [&>:last-child>span]:rounded"
				value={sliderValue}
				onValueChange={handleSliderChange}
				min={minValue}
				max={maxValue}
				aria-label={label}
			/>
			<Input
				className="h-8 w-12 px-2 py-1"
				type="text"
				inputMode="decimal"
				value={inputValues[0]}
				onChange={(e) => handleInputChange(e, 0)}
				onBlur={() => validateAndUpdateValue(inputValues[0], 0)}
				onKeyDown={(e) => {
					if (e.key === "Enter") {
						validateAndUpdateValue(inputValues[0], 0);
					}
				}}
				aria-label="Enter value"
			/>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

